const lead = $input.item.json;
const firstName = (lead.Name || 'there').split(' ')[0];
const subject = `Quick Idea for ${lead.Company}'s Online Presence`;
const htmlBody = `
<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #1e293b; max-width: 600px;">
  <p>Dear ${firstName},</p>
  <p>I came across <strong>${lead.Company}</strong> in ${lead.Location} and noticed you're currently running without your own website or app.</p>
  <p>I'm Hamzah from <strong>TechInnoSphere Software Solutions (Mumbai)</strong>. We build simple, affordable web platforms and ordering pages for local ${lead.Category} businesses so customers can find and order from you directly — no commission cut to third-party apps.</p>
  <p>Specifically for you: <strong>${lead.TechInterest}</strong>.</p>
  <p>Would you be open to a short 10-minute call this week to see a quick demo?</p>
  <p>Best regards,<br>
  <strong>Hamzah</strong><br>
  TechInnoSphere Software Solutions<br>
  contact@techinnosphere.com | www.techinnosphere.com</p>
</div>
`;
const plainText = `Hi ${firstName},\n\nI came across ${lead.Company} in ${lead.Location} and noticed you don't have your own website or app yet.\n\nWe build simple, affordable ordering websites for local businesses like yours — zero commission, direct customer orders.\n\nWould you be open to a 10-minute call this week?\n\nBest regards,\nHamzah | TechInnoSphere Software Solutions\ncontact@techinnosphere.com`;
return { json: { ...lead, emailSubject: subject, emailHtml: htmlBody, emailText: plainText } };
